stats.query:
-- numerator (372366) from the bills query above; denominator = 363 days actually traded.
-- 364 calendar days in the window, 354 distinct VoucherDates, 10 absent:
SELECT CAST(VoucherDate AS date) AS d, COUNT(*) AS bills FROM SaleHeader WHERE VoucherDate >= '2025-09-01' AND VoucherDate < '2026-08-31' GROUP BY CAST(VoucherDate AS date) ORDER BY 1;
-- 9 of the 10 (22-30 Sep 2025) were traded but stamped 2025-09-21 by a stuck till clock, proven by:
SELECT CAST(RecordDateTime AS date) AS rec_d, COUNT(*) AS bills FROM SaleHeader WHERE CAST(VoucherDate AS date)='2025-09-21' GROUP BY CAST(RecordDateTime AS date) ORDER BY 1;
-- leaving 2026-08-18 as the single genuinely closed day. 372366/363 = 1025.8
